import { Client, ClientEvents, Collection, GatewayIntentBits } from 'discord.js';
import path from 'path';
import { ExtendedClient } from './types/ExtendedClient';
import { EventHandler } from './handlers/EventHandler';
import { CommandHandler } from './handlers/CommandHandler';
import { Command } from './types/interfaces/Command/Command';
import { Event } from './types/interfaces/Event';
import { LogHandler } from './handlers/LogHandler';

const client: ExtendedClient = new Client({
    intents: [
        GatewayIntentBits.Guilds,
        GatewayIntentBits.GuildMessages,
        GatewayIntentBits.MessageContent
    ],
}) as ExtendedClient;

client.commands = new Collection<string, Command>();
client.events = new Collection<string, Event<keyof ClientEvents>>();
client.commandHandler = new CommandHandler(client, path.join(__dirname, 'commands'))
client.eventHandler = new EventHandler(client, path.join(__dirname, 'events'));
client.logHandler = new LogHandler();
client.database = {};
client.config = {};

async function main() {
    await client.login();
}

main().catch(console.error);